#!/bin/sh
# Generated by FWShift: a Google Cloud network firewall policy, created with gcloud. Read the report first: what is
# not written is listed there.
#
#   DRY_RUN=1 sh THIS_FILE                              prints the commands; needs no access to Google Cloud
#   GCLOUD_OPTS='--project my-project' sh THIS_FILE     creates the policy and its rules
#
# The policy is associated with no network: nothing changes for any traffic until you associate it:
#   gcloud compute network-firewall-policies associations create --firewall-policy fwshift --network NETWORK --global-firewall-policy
# It decides every connection of that network. Set the network's enforcement order to BEFORE_CLASSIC_FIREWALL, or
# the VPC firewall rules of the network decide first. A policy of the same name stops the script before anything is
# created; a command gcloud refuses stops it where it is (delete the policy and run it again).
set -u
DRY_RUN="${DRY_RUN:-}"
GCLOUD_OPTS="${GCLOUD_OPTS:-}"
POLICY=fwshift
fail() { printf 'FAILED: %s\n' "$*" >&2; exit 1; }
run() {
  if [ -n "$DRY_RUN" ]; then printf 'gcloud' >&2; printf ' %s' "$@" >&2; printf '\n' >&2; return 0; fi
  gcloud "$@" $GCLOUD_OPTS --quiet >/dev/null || fail "gcloud $1 $2 $3 $4"
}
if [ -z "$DRY_RUN" ] && gcloud compute network-firewall-policies describe "$POLICY" --global $GCLOUD_OPTS >/dev/null 2>&1; then
  fail "a network firewall policy named $POLICY exists already; nothing was created"
fi

run compute network-firewall-policies create "$POLICY" --global '--description=Generated by FWShift; review the conversion report before associating it'

run compute network-firewall-policies rules create 1000 --firewall-policy="$POLICY" --global-firewall-policy --direction=INGRESS --action=deny --src-ip-ranges=0.0.0.0/0 --dest-ip-ranges=192.0.2.66/32,198.51.100.0/24 --layer4-configs=all --enable-logging --description=block-bad
run compute network-firewall-policies rules create 1010 --firewall-policy="$POLICY" --global-firewall-policy --direction=EGRESS --action=deny --src-ip-ranges=0.0.0.0/0 --dest-ip-ranges=192.0.2.66/32,198.51.100.0/24 --layer4-configs=all --enable-logging --description=block-bad
run compute network-firewall-policies rules create 1020 --firewall-policy="$POLICY" --global-firewall-policy --direction=INGRESS --action=deny --src-ip-ranges=::/0 --dest-ip-ranges=2001:db8:10::/48 --layer4-configs=all --enable-logging --description=block-bad
run compute network-firewall-policies rules create 1030 --firewall-policy="$POLICY" --global-firewall-policy --direction=EGRESS --action=deny --src-ip-ranges=::/0 --dest-ip-ranges=2001:db8:10::/48 --layer4-configs=all --enable-logging --description=block-bad
run compute network-firewall-policies rules create 1040 --firewall-policy="$POLICY" --global-firewall-policy --direction=INGRESS --action=deny --src-ip-ranges=192.0.2.66/32,198.51.100.0/24 --dest-ip-ranges=0.0.0.0/0 --layer4-configs=all --description=global-block
run compute network-firewall-policies rules create 1050 --firewall-policy="$POLICY" --global-firewall-policy --direction=EGRESS --action=deny --src-ip-ranges=192.0.2.66/32,198.51.100.0/24 --dest-ip-ranges=0.0.0.0/0 --layer4-configs=all --description=global-block
run compute network-firewall-policies rules create 1060 --firewall-policy="$POLICY" --global-firewall-policy --direction=INGRESS --action=deny --src-ip-ranges=0.0.0.0/0 --dest-ip-ranges=0.0.0.0/0 --layer4-configs=all --description=fwshift-default-deny
run compute network-firewall-policies rules create 1070 --firewall-policy="$POLICY" --global-firewall-policy --direction=EGRESS --action=deny --src-ip-ranges=0.0.0.0/0 --dest-ip-ranges=0.0.0.0/0 --layer4-configs=all --description=fwshift-default-deny
run compute network-firewall-policies rules create 1080 --firewall-policy="$POLICY" --global-firewall-policy --direction=INGRESS --action=deny --src-ip-ranges=::/0 --dest-ip-ranges=::/0 --layer4-configs=all --description=fwshift-default-deny
run compute network-firewall-policies rules create 1090 --firewall-policy="$POLICY" --global-firewall-policy --direction=EGRESS --action=deny --src-ip-ranges=::/0 --dest-ip-ranges=::/0 --layer4-configs=all --description=fwshift-default-deny

# Not written:
#   web-out: the source of the rule is in zone trust, and a rule of Google Cloud names no zone: give the networks behind trust with --zone-network; the destination of the rule is in zone untrust, and a rule of Google Cloud names no zone: give the networks behind untrust with --zone-network
#   updates: the source of the rule is in zone trust, and a rule of Google Cloud names no zone: give the networks behind trust with --zone-network; host name object updates: the rules are written with addresses
#   ping-out: the source of the rule is in zone trust, and a rule of Google Cloud names no zone: give the networks behind trust with --zone-network; the destination of the rule is in zone untrust, and a rule of Google Cloud names no zone: give the networks behind untrust with --zone-network
#   web-in: the source of the rule is in zone untrust, and a rule of Google Cloud names no zone: give the networks behind untrust with --zone-network; the destination of the rule is in zone dmz, and a rule of Google Cloud names no zone: give the networks behind dmz with --zone-network
#   mail-in: the source of the rule is in zone untrust, and a rule of Google Cloud names no zone: give the networks behind untrust with --zone-network; the destination of the rule is in zone dmz, and a rule of Google Cloud names no zone: give the networks behind dmz with --zone-network
#   admin: the source of the rule is in zone trust, and a rule of Google Cloud names no zone: give the networks behind trust with --zone-network; the destination of the rule is in zone dmz, and a rule of Google Cloud names no zone: give the networks behind dmz with --zone-network
#   not-servers: the source of the rule is in zone trust, and a rule of Google Cloud names no zone: give the networks behind trust with --zone-network; the destination of the rule is in zone dmz, and a rule of Google Cloud names no zone: give the networks behind dmz with --zone-network
#   dmz-out: the source of the rule is in zone dmz, and a rule of Google Cloud names no zone: give the networks behind dmz with --zone-network; the destination of the rule is in zone untrust, and a rule of Google Cloud names no zone: give the networks behind untrust with --zone-network
#   guest-web: schedule 'work-hours' is not converted; the rule would apply at all times; the source of the rule is in zone guest, and a rule of Google Cloud names no zone: give the networks behind guest with --zone-network; the destination of the rule is in zone untrust, and a rule of Google Cloud names no zone: 
#   guest-ping: references 'junos-ping': the predefined application junos-ping: Juniper describes it as ICMP echo, other readers of Junos as every ICMP type; the source of the rule is in zone guest, and a rule of Google Cloud names no zone: give the networks behind guest with --zone-network; the destination of the 
#   intra: the source of the rule is in zone trust, and a rule of Google Cloud names no zone: give the networks behind trust with --zone-network; the destination of the rule is in zone trust, and a rule of Google Cloud names no zone: give the networks behind trust with --zone-network
#   global-ntp: the source of the rule is in zone trust, and a rule of Google Cloud names no zone: give the networks behind trust with --zone-network; the destination of the rule is in zone untrust, and a rule of Google Cloud names no zone: give the networks behind untrust with --zone-network

echo 'Done. Associate the policy with the network when you are ready; until then nothing changes.' >&2
